-- Seller invitation codes generated by a business administrator.
-- Sellers redeem a code to join exactly one business and, for a branchful
-- business, exactly one active branch. The API uses the service role key, so
-- row-level security blocks every direct anon/client read and write.

CREATE TABLE IF NOT EXISTS public.seller_invitations (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code text NOT NULL UNIQUE,
    business_id uuid NOT NULL,
    branch_id uuid,
    created_by uuid,
    status text NOT NULL DEFAULT 'active',
    used_by uuid,
    used_at timestamptz,
    expires_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS seller_invitations_business_created_idx
    ON public.seller_invitations (business_id, created_at DESC);

CREATE INDEX IF NOT EXISTS seller_invitations_code_idx
    ON public.seller_invitations (code);

ALTER TABLE public.seller_invitations ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'seller_invitations_status_check'
          AND conrelid = 'public.seller_invitations'::regclass
    ) THEN
        ALTER TABLE public.seller_invitations
            ADD CONSTRAINT seller_invitations_status_check
            CHECK (status IN ('active', 'used', 'revoked'));
    END IF;
END
$$;
